CREATE TABLE measurement_profiles (id VARCHAR(36) PRIMARY KEY,label VARCHAR(120) NOT NULL,category VARCHAR(60) NOT NULL,fit_preference VARCHAR(20) NOT NULL,preferred_unit VARCHAR(5) NOT NULL,created_at DATETIME(6),updated_at DATETIME(6));
CREATE TABLE body_measurements (profile_id VARCHAR(36) NOT NULL,dimension_type VARCHAR(30) NOT NULL,measurement_value DECIMAL(16,6) NOT NULL,PRIMARY KEY(profile_id,dimension_type),FOREIGN KEY(profile_id) REFERENCES measurement_profiles(id) ON DELETE CASCADE);
CREATE TABLE seller_charts (id VARCHAR(36) PRIMARY KEY,seller_name VARCHAR(120) NOT NULL,garment_name VARCHAR(120) NOT NULL,garment_category VARCHAR(60) NOT NULL,measurement_convention VARCHAR(30) NOT NULL,unit VARCHAR(5) NOT NULL,created_at DATETIME(6),updated_at DATETIME(6));
CREATE TABLE size_options (id VARCHAR(36) PRIMARY KEY,chart_id VARCHAR(36),display_order INT,label VARCHAR(80) NOT NULL,FOREIGN KEY(chart_id) REFERENCES seller_charts(id) ON DELETE CASCADE);
CREATE TABLE size_measurements (size_id VARCHAR(36) NOT NULL,dimension_type VARCHAR(30) NOT NULL,measurement_value DECIMAL(16,6) NOT NULL,PRIMARY KEY(size_id,dimension_type),FOREIGN KEY(size_id) REFERENCES size_options(id) ON DELETE CASCADE);
CREATE TABLE comparison_runs (id VARCHAR(36) PRIMARY KEY,profile_id VARCHAR(36) NOT NULL,chart_id VARCHAR(36) NOT NULL,created_at DATETIME(6),FOREIGN KEY(profile_id) REFERENCES measurement_profiles(id),FOREIGN KEY(chart_id) REFERENCES seller_charts(id));
